~~~~~~~~~~~~~~~~~~~~~~~~`.split('\n');
const dragons={'8,10':'S','10,11':'N','14,9':'W','10,13':'E'};
function init(){let E=[];for(let y=0;y<map.length;y++)for(let x=0;x<24;x++){const c=map[y][x];
 if(c=='g')E.push({t:'g',x,y});if(c=='d')E.push({t:'d',x,y,f:dragons[x+','+y],n:{'8,10':'A','10,11':'B','14,9':'C','10,13':'D'}[x+','+y]});if(c=='W')E.push({t:'W',x,y});}
 return {E,closed:false};}
const D={U:[0,-1],D:[0,1],L:[-1,0],R:[1,0]};
function water(s,x,y){if(x<0||y<0||x>=24||y>=21)return 'edge';const c=map[y][x];if(c=='~')return true;if(c=="'")return !s.closed;return false;}
function at(s,x,y){return s.E.find(e=>e.x==x&&e.y==y);}
function run(seq){const s=init();const log=[];let i=0;
 for(const m of seq.replace(/\s/g,'')){i++;const w=s.E.find(e=>e.t=='W');const [dx,dy]=D[m];
  let chain=[];let x=w.x+dx,y=w.y+dy;
  while(true){if(x<0||y<0||x>=24||y>=21){chain=null;break;}const e=at(s,x,y);if(e){chain.push(e);x+=dx;y+=dy;continue;}break;}
  if(chain===null){log.push(i+m+' refused edge');return {s,log,fail:true};}
  if(chain.length==0&&water(s,w.x+dx,w.y+dy)){log.push(i+m+' refused water');return {s,log,fail:true};}
  for(const e of chain.reverse()){e.x+=dx;e.y+=dy;}w.x+=dx;w.y+=dy;
  // drown
  for(const e of [...s.E]) if(water(s,e.x,e.y)===true){log.push(i+m+' drown '+(e.n||e.t)+'@'+e.x+','+e.y);s.E.splice(s.E.indexOf(e),1);}
  // breath
  const vict=new Set();
  for(const d of s.E.filter(e=>e.t=='d')){const f={N:[0,-1],S:[0,1],W:[-1,0],E:[1,0]}[d.f];let x=d.x+f[0],y=d.y+f[1];
   while(x>=0&&y>=0&&x<24&&y<21){const e=at(s,x,y);if(e){vict.add(e);log.push(i+m+' '+d.n+' kills '+(e.n||e.t)+'@'+x+','+y);break;}x+=f[0];y+=f[1];}}
  for(const e of vict)s.E.splice(s.E.indexOf(e),1);
  // goblin adjacency to warrior
  const w2=s.E.find(e=>e.t=='W');
  if(!w2){log.push('WARRIOR DEAD');return {s,log,fail:true};}
  if(s.E.some(e=>e.t=='g'&&Math.abs(e.x-w2.x)+Math.abs(e.y-w2.y)==1)){log.push('GOBLIN KILLS W');return {s,log,fail:true};}
  if(!s.E.some(e=>e.t=='g'||e.t=='d')){if(!s.closed)log.push(i+m+' gates close');s.closed=true;}
 }
 return {s,log};}
function show(r){const g=map.map(r=>r.replace(/[gdW]/g,'.').split(''));for(const e of r.s.E)g[e.y][e.x]=e.t=='d'?e.n:e.t;console.log(g.map((r,y)=>(y+'').padStart(2)+' '+r.join('')).join('\n'));console.log(r.log.join('\n'));const w=r.s.E.find(e=>e.t=='W');console.log('W',w&&w.x,w&&w.y,'monsters',r.s.E.filter(e=>e.t!='W').length);}
globalThis.run=run;globalThis.show=show;
show(run('RRRDDDLU'));

